import { useState } from 'react';
import { Button, Drawer, Menu, MenuItem, MenuDivider } from '@jinx-ui/react';

type NavKey = 'projects' | 'team' | 'settings' | 'logout';

interface MenuDrawerProps {
  onNavigate: (key: NavKey) => void;
}

const NAV_ITEMS: ReadonlyArray<{ key: NavKey; label: string }> = [
  { key: 'projects', label: 'Проекты' },
  { key: 'team', label: 'Команда' },
  { key: 'settings', label: 'Настройки' },
];

export default function MenuDrawer({ onNavigate }: MenuDrawerProps) {
  const [open, setOpen] = useState(false);

  const select = (key: NavKey) => {
    onNavigate(key);
    setOpen(false);
  };

  return (
    <>
      <Button variant="secondary" onClick={() => setOpen(true)}>
        Меню
      </Button>

      <Drawer
        open={open}
        placement="left"
        title="Навигация"
        onClose={() => setOpen(false)}
        style={{ width: 'var(--jx-size-drawer-sm)' }}
      >
        <Menu aria-label="Навигация">
          {NAV_ITEMS.map((item) => (
            <MenuItem key={item.key} onClick={() => select(item.key)}>
              {item.label}
            </MenuItem>
          ))}
          <MenuDivider />
          <MenuItem tone="danger" onClick={() => select('logout')}>
            Выйти
          </MenuItem>
        </Menu>
      </Drawer>
    </>
  );
}

